class Solution:

	def solve(self, ind, S, target, evalu, ans, res, mul):
		if ind == len(S):
			if evalu == target:
				res.append(ans)
			return
		for i in range(ind, len(S)):
			if ind != i and S[ind] == '0':
				break
			cur = int(S[ind:i + 1])
			if ind == 0:
				self.solve(i + 1, S, target, cur, ans + str(cur), res, cur)
			else:
				self.solve(i + 1, S, target, evalu + cur, ans + '+' + str(cur), res, cur)
				self.solve(i + 1, S, target, evalu - cur, ans + '-' + str(cur), res, -cur)
				self.solve(i + 1, S, target, evalu - mul + mul * cur, ans + '*' + str(cur), res, mul * cur)

	def addOperators(self, S, target):
		if int(S) == target:
			return [S]
		ans = ''
		res = []
		self.solve(0, S, target, 0, ans, res, 0)
		return res
